#include <stdio.h>
#include <string.h>

void oCopiador(void) {
    char palavra[50] = "";
    scanf("%49s", palavra);
    char copia[50] = "?????????????????????";
    int i = 0;
    for (i = 0; palavra[i] != '\0'; i++) {
        copia[i] = palavra[i];
    }
    copia[i] = '\0';
    palavra[0] = '-';
    printf("%s\n", palavra);
    printf("%s\n", copia);
}
